struct nglListNode;

template <class T1, class T2>
struct pair { T1 first; T2 second; };
typedef pair<nglListNode *, unsigned int> node_pair;

class nglTransCompare {
public:
  bool operator()(const node_pair& NodeA, const node_pair& NodeB) {
    if ((float&)NodeA.second > (float&)NodeB.second) return true;
    else if ((float&)NodeA.second < (float&)NodeB.second) return false;
    else return (unsigned int)NodeA.first < (unsigned int)NodeB.first;
  }
};

extern "C" void partial_sort_impl(node_pair *, node_pair *, node_pair *, node_pair *, node_pair *, nglTransCompare)
  __asm__("__partial_sort__H3ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X01X01PX11X21_v");
extern "C" node_pair *unguarded_partition_impl(node_pair *, node_pair *, const node_pair &, nglTransCompare)
  __asm__("__unguarded_partition__H3ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZ15nglTransCompare_X01X01X11X21_X01");

static const node_pair &median_impl(const node_pair &a, const node_pair &b, const node_pair &c, nglTransCompare comp) {
  if (comp(a, b))
    if (comp(b, c)) return b;
    else if (comp(a, c)) return c;
    else return a;
  else if (comp(a, c)) return a;
  else if (comp(b, c)) return c;
  else return b;
}

extern "C" void introsort_loop_impl(node_pair *, node_pair *, node_pair *, int, nglTransCompare)
  __asm__("__introsort_loop__H4ZPt4pair2ZP11nglListNodeZUiZt4pair2ZP11nglListNodeZUiZiZ15nglTransCompare_X01X01PX11X21X31_v");
void introsort_loop_impl(node_pair *first, node_pair *last, node_pair *, int depth_limit, nglTransCompare comp) {
  while (last - first > 16) {
    if (depth_limit == 0) {
      partial_sort_impl(first, last, last, (node_pair *)0, (node_pair *)0, comp);
      return;
    }
    --depth_limit;
    node_pair *cut = unguarded_partition_impl(first, last,
      node_pair(median_impl(*first, *(first + (last - first) / 2), *(last - 1), comp)), comp);
    introsort_loop_impl(cut, last, (node_pair *)0, depth_limit, comp);
    last = cut;
  }
}
